:root{
  --primary:#094074;--primary-rgb:9,64,116;--on-primary:#fff;
  --secondary:#3C6997;--on-secondary:#fff;--accent:#5ADBFF;--on-accent:#13283a;
  --highlight:#FFDD4A;--on-highlight:#13283a;--warm:#FE9000;--on-warm:#13283a;
  --ink:#13283a;--ink-2:#355066;--muted:#6b7d8c;--line:#d9e3e9;
  --bg:#f2f7fa;--card:#fff;--surface:#fff;--surface-2:#f5f8fa;--surface-3:#edf3f6;
  --danger:#b83a3a;--success:#166b46;--warning:#7b4b00;
  --shadow:0 12px 34px rgba(16,42,61,.09);--shadow-lg:0 22px 58px rgba(16,42,61,.15);--r:18px;
  --p:var(--primary);--p2:var(--secondary);--a:var(--accent);--y:var(--highlight);--o:var(--warm);
  --cl-primary:var(--primary);--cl-primary-dark:var(--primary);--cl-primary-soft:color-mix(in srgb,var(--primary) 11%,white);
  --cl-accent:var(--warm);--cl-accent-soft:color-mix(in srgb,var(--highlight) 28%,white);
  --cl-ink:#102b42;--cl-ink-2:var(--ink);--cl-muted:var(--muted);--cl-line:var(--line);--cl-line-strong:#b8cbd6;
  --cl-shadow:var(--shadow);--cl-shadow-lg:var(--shadow-lg);--cl-radius:var(--r);
}
body[data-palette="rose"]{--primary:#64113F;--primary-rgb:100,17,63;--on-primary:#fff;--secondary:#DE4D86;--on-secondary:#111;--accent:#84E6F8;--on-accent:#13283a;--highlight:#F7CACD;--on-highlight:#13283a;--warm:#F29CA3;--on-warm:#13283a}
body[data-palette="citrus"]{--primary:#61E8E1;--primary-rgb:97,232,225;--on-primary:#13283a;--secondary:#F25757;--on-secondary:#111;--accent:#F2E863;--on-accent:#13283a;--highlight:#F2CD60;--on-highlight:#13283a;--warm:#EAF2E3;--on-warm:#13283a}
body[data-palette="ocean"]{--primary:#094074;--primary-rgb:9,64,116;--on-primary:#fff;--secondary:#3C6997;--on-secondary:#fff;--accent:#5ADBFF;--on-accent:#13283a;--highlight:#FFDD4A;--on-highlight:#13283a;--warm:#FE9000;--on-warm:#13283a}
body[data-palette="signal"]{--primary:#D00000;--primary-rgb:208,0,0;--on-primary:#fff;--secondary:#3F88C5;--on-secondary:#fff;--accent:#136F63;--on-accent:#fff;--highlight:#FFBA08;--on-highlight:#032B43;--warm:#032B43;--on-warm:#fff}
body[data-palette="woodland"]{--primary:#606C38;--primary-rgb:96,108,56;--on-primary:#fff;--secondary:#283618;--on-secondary:#fff;--accent:#DDA15E;--on-accent:#283618;--highlight:#FEFAE0;--on-highlight:#283618;--warm:#BC6C25;--on-warm:#fff}
body[data-palette="tranquil"]{--primary:#1F363D;--primary-rgb:31,54,61;--on-primary:#fff;--secondary:#40798C;--on-secondary:#fff;--accent:#70A9A1;--on-accent:#1F363D;--highlight:#CFE0C3;--on-highlight:#1F363D;--warm:#9EC1A3;--on-warm:#1F363D}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:var(--bg)}button,input,select,textarea{font:inherit}button{cursor:pointer}a{text-decoration:none;color:inherit}svg{display:block}.hidden{display:none!important}.muted{color:var(--muted)!important}.small{font-size:.82rem}.mono{font-family:"SFMono-Regular",Consolas,"Liberation Mono",monospace}.eyebrow{font-size:.74rem;font-weight:900;letter-spacing:.11em;text-transform:uppercase;color:var(--primary)}
.app-shell{min-height:100vh}.sidebar{position:fixed;inset:0 auto 0 0;width:280px;padding:24px 18px;background:#102b42;color:#fff;overflow-y:auto;z-index:30;box-shadow:14px 0 36px rgba(9,28,42,.12)}.brand{display:flex;align-items:center;gap:13px;padding:6px 8px 24px;text-decoration:none}.brand-mark{width:46px;height:46px;border-radius:15px;display:grid;place-items:center;background:var(--highlight);color:var(--on-highlight);font-weight:950;flex:0 0 auto}.brand strong{display:block;font-size:1.02rem}.brand span{display:block;font-size:.77rem;color:#b6c5cf;margin-top:3px}.side-label{padding:14px 12px 8px;color:#8499a7;font-size:.68rem;font-weight:850;letter-spacing:.13em;text-transform:uppercase}.side-nav{display:grid;gap:5px}.nav-link{display:flex;align-items:center;gap:12px;width:100%;border:0;border-radius:13px;padding:12px 13px;background:transparent;color:#c8d5de;text-align:left;font-weight:750;transition:.15s ease}.nav-link:hover{background:#173a54;color:#fff}.nav-link.active{color:#fff;background:#1b405b;box-shadow:inset 3px 0 var(--highlight)}.nav-icon{width:20px;text-align:center}.sidebar-bottom{margin-top:28px;padding:14px 8px;border-top:1px solid #27455b}.user-mini{display:flex;gap:11px;align-items:center}.avatar{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:var(--on-accent);font-weight:900;flex:0 0 auto}.user-mini strong{display:block;font-size:.86rem;overflow-wrap:anywhere}.user-mini span{display:block;color:#9fb0bc;font-size:.72rem;margin-top:2px}
.main{margin-left:280px;min-height:100vh}.topbar{position:sticky;top:0;z-index:20;min-height:78px;padding:16px 28px;display:flex;align-items:center;justify-content:space-between;gap:18px;background:#f8fbfd;border-bottom:1px solid var(--line)}.topbar-left{display:flex;align-items:center;gap:14px}.page-kicker{font-size:.78rem;color:var(--muted);font-weight:700}.page-title{font-size:1.27rem;font-weight:900;margin-top:2px}.top-actions{display:flex;align-items:center;gap:10px}.icon-btn{border:1px solid var(--line);background:#fff;color:var(--ink);width:42px;height:42px;border-radius:13px;display:grid;place-items:center;box-shadow:0 5px 16px rgba(16,42,61,.06)}.mobile-menu{display:none}.content{padding:28px;max-width:1700px;margin:0 auto;min-width:0}
.hero{position:relative;padding:34px;border-radius:24px;color:var(--on-primary);background:var(--primary);box-shadow:var(--shadow-lg)}.hero-content{position:relative}.hero h1{font-size:clamp(2rem,4vw,3.25rem);line-height:1.04;margin:8px 0 12px;letter-spacing:-.045em}.hero p{margin:0;max-width:680px;color:color-mix(in srgb,var(--on-primary) 80%,transparent);font-size:1.02rem;line-height:1.65}.hero .eyebrow{color:var(--highlight)}.hero-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.section{margin-top:24px}.section-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:14px}.section-head h2{margin:0;font-size:1.24rem;letter-spacing:-.02em}.section-head p{margin:5px 0 0;color:var(--muted);font-size:.9rem}
.grid{display:grid;gap:18px;min-width:0}.grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}.stat-card,.card{background:#fff;border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow);min-width:0}.stat-card{padding:20px}.stat-value{font-size:1.8rem;font-weight:950;letter-spacing:-.04em}.stat-label{font-weight:850;margin-top:3px}.stat-note{font-size:.78rem;color:var(--muted);margin-top:6px}.card{padding:20px}.card h3{margin-top:0}
.btn{border:0;border-radius:12px;padding:10px 14px;font-weight:850;display:inline-flex;align-items:center;justify-content:center;gap:8px}.btn-primary{background:var(--primary)!important;color:var(--on-primary)!important;border-color:var(--primary)!important}.btn-secondary{background:var(--secondary)!important;color:var(--on-secondary)!important}.btn-accent{background:var(--highlight)!important;color:var(--on-highlight)!important}.btn-light{background:#fff!important;color:#163047!important}.btn-soft{background:color-mix(in srgb,var(--primary) 11%,white)!important;color:var(--ink)!important;border:1px solid color-mix(in srgb,var(--primary) 28%,white)!important}.btn-ghost{background:#fff!important;color:var(--ink)!important;border:1px solid var(--line)!important}.btn-danger{background:#fff0f0!important;color:#8c2727!important;border:1px solid #e5b4b4!important}.btn-sm{padding:8px 11px!important;border-radius:10px!important;font-size:.82rem!important}.btn-outline-primary{border:1px solid var(--primary)!important;color:var(--primary)!important;background:#fff!important}.btn-outline-primary:hover{background:var(--primary)!important;color:var(--on-primary)!important}.btn-outline-secondary{border:1px solid #8da0ae!important;color:#324b5f!important;background:#fff!important}.btn-outline-light{border:1px solid #fff!important;color:#fff!important;background:transparent!important}
.badge{display:inline-flex;align-items:center;gap:5px;padding:6px 9px;border-radius:999px;font-size:.72rem;font-weight:850;background:#e8eef2;color:#193247;border:1px solid #cbd8df}.badge.good,.text-bg-success{background:#e6f6ed!important;color:#0f5d3c!important;border-color:#9fceb5!important}.badge.warn,.text-bg-warning{background:#fff3d2!important;color:#6e4300!important;border-color:#e7c979!important}.badge.info{background:color-mix(in srgb,var(--primary) 12%,white)!important;color:#173146!important;border-color:color-mix(in srgb,var(--primary) 38%,white)!important}.badge.danger,.text-bg-danger{background:#fff0f0!important;color:#842727!important;border-color:#e4b1b1!important}.text-bg-secondary,.text-bg-light{background:#e9eef2!important;color:#193247!important;border:1px solid #cbd8df!important}.badge.permanent{background:var(--primary)!important;color:var(--on-primary)!important;border-color:var(--primary)!important}
.course-card{padding:0;overflow:hidden}.course-cover{height:132px;position:relative;padding:18px;color:var(--on-primary);background:var(--primary)}.course-level{display:inline-flex;padding:6px 10px;border-radius:999px;background:color-mix(in srgb,var(--on-primary) 15%,transparent);border:1px solid color-mix(in srgb,var(--on-primary) 28%,transparent);color:var(--on-primary);font-weight:850;font-size:.72rem}.course-body{padding:18px}.course-title{font-weight:900;font-size:1.03rem}.course-meta{margin-top:7px;color:var(--muted);font-size:.82rem}.course-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:15px;flex-wrap:wrap}.progress{height:9px;background:#e5edf1;border-radius:999px;overflow:hidden}.progress span,.progress-bar{display:block;height:100%;background:var(--primary)!important;color:var(--on-primary)!important;border-radius:inherit}
.panel-tabs{display:flex;gap:6px;flex-wrap:wrap;padding:6px;border:1px solid var(--line);border-radius:15px;background:#fff;box-shadow:var(--shadow)}.tab-btn{border:0;background:transparent;color:var(--muted);padding:10px 13px;border-radius:10px;font-weight:850}.tab-btn:hover{color:var(--primary);background:var(--surface-2)}.tab-btn.active{color:var(--on-primary);background:var(--primary)}.tab-panel{display:none;margin-top:20px}.tab-panel.active{display:block}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:14px}.search-wrap{position:relative;min-width:280px;flex:1;max-width:470px}.search-wrap input{padding-left:40px}.search-icon{position:absolute;left:13px;top:9px;color:var(--muted);font-size:1.15rem}
.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:16px;background:#fff;width:100%;min-width:0}.table-wrap table{border-collapse:collapse;width:100%;min-width:760px}.table-wrap th,.table-wrap td{padding:14px 15px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle}.table-wrap th{font-size:.73rem;letter-spacing:.07em;text-transform:uppercase;color:#526878;background:#f1f5f7}.table-wrap td{font-size:.88rem}.table-wrap tr:last-child td{border-bottom:0}.person{display:flex;align-items:center;gap:10px}.person .avatar{width:36px;height:36px;font-size:.77rem}.row-actions{display:flex;gap:7px;justify-content:flex-end;flex-wrap:wrap}
.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field{display:grid;gap:7px;min-width:0}.field.full{grid-column:1/-1}.field label{font-size:.79rem;font-weight:850;color:var(--ink-2)}input,select,textarea{width:100%;border:1px solid var(--line);border-radius:11px;padding:11px 12px;background:#fff;color:var(--ink);outline:none}input:focus,select:focus,textarea:focus{border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 16%,transparent)}textarea{min-height:150px;resize:vertical}.help{font-size:.75rem;color:var(--muted);line-height:1.5}.divider{height:1px;background:var(--line);margin:20px 0}.list{display:grid;gap:10px}.list-item{padding:14px;border:1px solid var(--line);border-radius:13px;background:#fff;display:flex;align-items:center;justify-content:space-between;gap:14px;min-width:0}.list-item strong{font-size:.9rem}.list-item p{margin:4px 0 0;color:var(--muted);font-size:.78rem}.empty{padding:32px;border:1px dashed #b8cbd6;border-radius:16px;text-align:center;color:var(--muted);background:#fff}.chip-row,.role-list{display:flex;gap:7px;flex-wrap:wrap}
.admin-shell{display:grid;grid-template-columns:230px minmax(0,1fr);gap:20px;width:100%;min-width:0}.admin-shell>div{min-width:0;width:100%}.admin-nav{position:sticky;top:100px;align-self:start;padding:12px;border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:var(--shadow)}.admin-nav button,.admin-nav a{width:100%;border:0;background:transparent;text-align:left;padding:11px 12px;border-radius:11px;color:var(--muted);font-weight:850;display:block}.admin-nav button:hover,.admin-nav a:hover{background:var(--surface-2);color:var(--primary)}.admin-nav button.active,.admin-nav a.active{background:color-mix(in srgb,var(--primary) 12%,white);color:#173146;border-left:3px solid var(--primary)}.admin-panel{display:none;width:100%;min-width:0}.admin-panel.active{display:block}.admin-panel>.grid,.admin-panel>.card,.admin-panel>.table-wrap,.admin-panel>.toolbar,.admin-panel>.notice{width:100%}.notice{display:flex;gap:12px;padding:14px 16px;border-radius:13px;background:color-mix(in srgb,var(--primary) 8%,white);color:var(--ink-2);border:1px solid color-mix(in srgb,var(--primary) 30%,white);font-size:.86rem;line-height:1.5}.notice strong{color:var(--ink)}
.theme-studio{display:grid;grid-template-columns:310px minmax(0,1fr);gap:18px;width:100%;min-width:0}.theme-preview{border:1px solid var(--line);border-radius:18px;overflow:hidden;background:#f7fafc;min-height:390px}.preview-top{padding:12px 16px;background:var(--primary);color:var(--on-primary);display:flex;justify-content:space-between}.preview-hero{margin:18px;padding:24px;border-radius:18px;background:var(--secondary);color:var(--on-secondary)}.preview-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:0 18px 18px}.preview-card{padding:14px;border-radius:14px;background:#fff;border:1px solid var(--line)}.theme-file-tabs{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:10px}.theme-file-tab{border:0;background:var(--surface-3);padding:8px 10px;border-radius:9px;font-size:.77rem;font-weight:850}.theme-file-tab.active{background:var(--primary);color:var(--on-primary)}.theme-editor-area{min-height:300px;background:#0d1922;color:#d7e8f3;border-color:#0d1922;font-family:"SFMono-Regular",Consolas,monospace;font-size:.78rem;line-height:1.6}
.palette-dock{position:fixed;right:22px;bottom:22px;z-index:60;width:292px;padding:14px;border-radius:18px;background:#fff;border:1px solid var(--line);box-shadow:0 18px 55px rgba(15,36,52,.20)}.palette-head{display:flex;justify-content:space-between;align-items:center;gap:10px}.palette-options{display:grid;gap:8px;margin-top:10px}.palette-option{border:1px solid var(--line);border-radius:12px;padding:8px;background:#fff;display:flex;align-items:center;gap:10px;text-align:left}.palette-option.active{border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 12%,transparent)}.swatches{display:flex;gap:3px}.swatch{display:block;width:22px;height:22px;border-radius:7px}.palette-name{font-size:.75rem;font-weight:850}.footer-note{padding:26px 0 90px;text-align:center;color:var(--muted);font-size:.78rem}
.modal-backdrop{position:fixed;inset:0;z-index:100;background:rgba(7,20,30,.56);display:none;align-items:center;justify-content:center;padding:18px}.modal-backdrop.open{display:flex}.modal-card{width:min(700px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:22px;box-shadow:0 30px 90px rgba(0,0,0,.30)}.modal-head,.modal-foot{padding:18px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px}.modal-head{border-bottom:1px solid var(--line)}.modal-head h3{margin:0}.modal-body{padding:20px}.modal-foot{border-top:1px solid var(--line);justify-content:flex-end}.close-btn{border:0;background:var(--surface-3);width:34px;height:34px;border-radius:10px}.quick-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.quick-action{border:1px solid var(--line);border-radius:15px;padding:17px;background:#fff;text-align:left}.quick-action:hover{border-color:var(--primary);box-shadow:var(--shadow)}.quick-action strong{display:block;margin-bottom:4px}.quick-action span{font-size:.78rem;color:var(--muted)}
.account-menu{position:relative}.account-menu>summary{list-style:none;cursor:pointer}.account-menu>summary::-webkit-details-marker{display:none}.account-menu-panel{position:absolute;right:0;top:calc(100% + 8px);z-index:80;min-width:190px;padding:7px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow-lg);display:grid}.account-menu-panel a{padding:9px 11px;border-radius:8px;color:var(--ink-2);font-weight:800;white-space:nowrap}.account-menu-panel a:hover{background:var(--surface-2);color:var(--primary)}.flash-stack{display:grid;gap:8px;margin-bottom:18px}.flash{padding:13px 15px;border-radius:12px;border:1px solid var(--line);background:#fff}.flash-success{border-color:#a8dcc1;background:#effaf4}.flash-danger{border-color:#efbcbc;background:#fff2f2}.flash-warning{border-color:#f1d38e;background:#fff9e9}.public-shell{min-height:100vh}.public-nav{position:sticky;top:0;z-index:30;background:#f8fbfd;border-bottom:1px solid var(--line)}.public-nav-inner{max-width:1320px;margin:auto;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;gap:20px}.public-links{display:flex;gap:8px;align-items:center}.public-main{max-width:1320px;margin:auto;padding:28px 24px;min-width:0}
/* Bootstrap compatibility for authoring and legacy course templates */
.container,.container-lg,.container-xl{max-width:1320px}.container-fluid.cl-container-wide{max-width:1600px;margin-inline:auto}.cl-container-course{max-width:1540px;margin-inline:auto}.text-body-secondary{color:var(--muted)!important}.bg-body-tertiary{background:var(--bg)!important}.card-header{background:#f5f8fa!important;border-color:var(--line)!important}.form-control,.form-select{border-color:var(--line)!important}.alert{border-radius:12px}.cl-admin-tabs{display:flex;gap:8px;flex-wrap:wrap}.cl-admin-tabs a{padding:9px 12px;border:1px solid var(--line);border-radius:10px;background:#fff;color:var(--ink-2);font-weight:800}.cl-admin-tabs a:hover{border-color:var(--primary);color:var(--primary)}details>summary.btn{list-style:none}details>summary.btn::-webkit-details-marker{display:none}.popover-form{position:absolute;right:28px;z-index:45;width:min(620px,calc(100vw - 40px));margin-top:8px;box-shadow:0 28px 80px rgba(15,36,52,.24)}.editor-choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.editor-choice{display:flex;align-items:center;gap:8px;padding:10px;border:1px solid var(--line);border-radius:10px;background:#fff}.editor-choice input{width:auto}#danger{scroll-margin-top:110px}
@media(max-width:1180px){.grid-4{grid-template-columns:repeat(2,1fr)}.theme-studio{grid-template-columns:1fr}.admin-shell{grid-template-columns:1fr}.admin-nav{position:static;display:flex;overflow:auto}.admin-nav button,.admin-nav a{white-space:nowrap;width:auto}.popover-form{right:18px}.editor-choice-grid{grid-template-columns:1fr}}
@media(max-width:860px){.sidebar{transform:translateX(-100%);transition:.2s}.sidebar.open{transform:none}.main{margin-left:0}.mobile-menu{display:grid}.content{padding:20px}.topbar{padding:14px 18px}.grid-3,.grid-2,.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.palette-dock{right:12px;bottom:12px;width:min(292px,calc(100vw - 24px))}.quick-actions{grid-template-columns:1fr}.popover-form{left:12px;right:12px;width:auto}}
@media(max-width:560px){.grid-4{grid-template-columns:1fr}.hero{padding:25px}.top-actions>.btn{display:none}.public-nav-inner{padding:12px 15px}.public-main{padding:20px 15px}}

/* Course player and authoring compatibility retained from the proven v0.3 presentation. */
.cl-hero {
  background-color: #102b42;
  background-image: var(--cl-hero-image);
  background-position: center;
  background-repeat: no-repeat;
  background-size: cover;
  color: #fff;
}
.cl-hero h1, .cl-hero h2, .cl-hero .lead, .cl-hero p, .cl-hero li { color: #fff; }
.cl-kicker {
  display: inline-block;
  color: var(--cl-accent);
  font-size: .73rem;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
}
.cl-hero .cl-kicker { color: #f3bd72; }
.cl-page-head .cl-kicker { color: color-mix(in srgb,var(--on-primary) 78%,transparent); }
.cl-hero-card {
  background: rgba(255, 255, 255, .09);
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 1.25rem;
  padding: 1.35rem;
  backdrop-filter: blur(12px);
}

.cl-page-head {
  color: var(--on-primary);
  background: var(--primary);
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.cl-page-head h1, .cl-page-head h2 { color: var(--on-primary); }
.cl-page-head .lead { color: color-mix(in srgb,var(--on-primary) 82%,transparent); }
.cl-back-link { color: var(--on-primary); text-decoration: none; font-weight: 700; }
.cl-back-link:hover { color: var(--on-primary); text-decoration: underline; }

.cl-band { background: #e8eef0; border-block: 1px solid var(--cl-line); }
.cl-category {
  height: 100%;
  padding: 1.4rem;
  background: white;
  border: 1px solid var(--cl-line);
  border-radius: var(--cl-radius);
  color: var(--cl-ink);
  font-weight: 800;
